// Shared builders and the deterministic fuzz-corpus digest. This exact text is
// compiled into the generator (via `include!`) and emitted verbatim into
// `golden.rs` (via `include_str!`), so the values captured as byte fixtures are
// guaranteed to be produced by the same construction this crate will re-run.
//
// Every item here relies on the enclosing module's `use` of the foreign and
// aarch64 items; it deliberately contains no `use` of its own so it drops
// cleanly into a module that imports them via `super::*` / `super::aarch64::*`.

/// A state snapshot with a distinct byte pattern in every field, so any offset
/// shift in the wire layout perturbs at least one fixture byte.
fn patterned_state() -> Aarch64StateV1 {
    let mut state = Aarch64StateV1::default();
    let mut i = 0;
    while i < state.x.len() {
        state.x[i] = 0x2000_0000_0000_0000u64
            .wrapping_add((i as u64) << 40)
            .wrapping_add((i as u64) << 8)
            .wrapping_add(i as u64);
        i += 1;
    }
    state.sp = 0x0011_2233_4455_6670;
    state.pc = 0x0a0b_0c0d_0e0f_1010;
    state.pstate = 0x3132_3334_3536_3738;
    state.tpidr_el0 = 0x4142_4344_4546_4748;
    state.tpidrro_el0 = 0x5152_5354_5556_5758;
    let mut v = 0;
    while v < state.vectors.len() {
        state.vectors[v].low = 0x6000_0000_0000_0000u64
            .wrapping_add((v as u64) << 32)
            .wrapping_add(v as u64);
        state.vectors[v].high = 0x7000_0000_0000_0000u64
            .wrapping_add((v as u64) << 32)
            .wrapping_add(v as u64);
        v += 1;
    }
    state.fpcr = 0x8182_8384;
    state.fpsr = 0x9192_9394;
    state.exception.kind = 0xa1a2_a3a4;
    state.exception.flags = 0xb1b2_b3b4;
    state.exception.esr = 0xc1c2_c3c4_c5c6_c7c8;
    state.exception.far = 0xd1d2_d3d4_d5d6_d7d8;
    state.exception.pc = 0xe1e2_e3e4_e5e6_e7e8;
    state
}

fn v1_supervisor_exit() -> ForeignMessageV1 {
    ForeignMessageV1::new_exit(
        ExitReason::SupervisorCall,
        0x1122_3344_5566_7788,
        0x99aa_bbcc_ddee_ff00,
        0x0102_0304_0506_0708,
        patterned_state(),
    )
    .expect("supervisor-call is a valid V1 exit")
}

fn v1_exception_exit() -> ForeignMessageV1 {
    ForeignMessageV1::new_exit(
        ExitReason::Exception,
        0x2233_4455_6677_8899,
        0xaabb_ccdd_eeff_0011,
        0x1112_1314_1516_1718,
        patterned_state(),
    )
    .expect("exceptions are valid V1 exits")
}

