/// A resume reply carrying a patterned state, built from a V1 supervisor exit
/// bound to domain `0x1122_3344_5566_7788`.
fn resume_reply() -> ForeignMessageV1 {
    v1_supervisor_exit().to_resume_reply(|state| {
        *state = patterned_state();
        state.x[0] = 0x0f1e_2d3c_4b5a_6978;
        state.x[30] = 0x8796_a5b4_c3d2_e1f0;
        state.pc = 0x0000_0000_0000_4004;
        state.sp = 0x0000_0000_0000_8000;
    })
}

fn terminate_reply() -> ForeignMessageV1 {
    v1_supervisor_exit().to_terminate_reply()
}

fn wait_park_no_timeout() -> ForeignWaitU32RequestV1 {
    ForeignWaitU32RequestV1::park(0x1122_3344_5566_7788, 0x0000_0000_0000_4000, 0xfeed_beef, None)
}

fn wait_park_timeout() -> ForeignWaitU32RequestV1 {
    ForeignWaitU32RequestV1::park(
        0x99aa_bbcc_ddee_ff00,
        0x0000_0000_dead_0000,
        0x0bad_f00d,
        Some(0x0102_0304_0506_0708),
    )
}

fn wait_wake() -> ForeignWaitU32RequestV1 {
    ForeignWaitU32RequestV1::wake(0x0000_0000_cafe_0000, 0x1234_5678)
}

fn wait_requeue() -> ForeignWaitU32RequestV1 {
    ForeignWaitU32RequestV1::requeue(0x0000_0000_1111_0000, 0x0000_0007, 0x0000_0000_2222_0000, 0x0000_0009)
}

fn wait_interrupt() -> ForeignWaitU32RequestV1 {
    ForeignWaitU32RequestV1::interrupt(0xaabb_ccdd_eeff_0011)
}

/// Read the first tail word (`reserved[0]`) directly from the encoded record.
/// The `KICK_ORIGIN_*` / `WAIT_OUTCOME_*` wire constants are private, so their
/// values can only be probed through the public encode path.
fn reserved0_on_wire(message: &ForeignMessageV1) -> u64 {
    let b = message.to_wire_bytes();
    u64::from_le_bytes([b[944], b[945], b[946], b[947], b[948], b[949], b[950], b[951]])
}

/// Read the encoded wait-operation discriminant (`WAIT_OPERATION_*`, private).
fn operation_on_wire(request: &ForeignWaitU32RequestV1) -> u16 {
    let b = request.to_wire_bytes();
    u16::from_le_bytes([b[6], b[7]])
}

/// SplitMix64: copied verbatim from the deterministic wire-fuzz test so the
/// frozen corpus is bit-identical. Do not modernize.
fn next_fuzz_word(seed: &mut u64) -> u64 {
    *seed = seed.wrapping_add(0x9e37_79b9_7f4a_7c15);
    let mut value = *seed;
    value = (value ^ (value >> 30)).wrapping_mul(0xbf58_476d_1ce4_e5b9);
    value = (value ^ (value >> 27)).wrapping_mul(0x94d0_49bb_1331_11eb);
    value ^ (value >> 31)
}

/// FNV-1a 64-bit, folding each byte in turn. Bundled so the digest is
/// self-contained in the fixture module.
fn fnv1a_update(hash: &mut u64, bytes: &[u8]) {
    let mut i = 0;
    while i < bytes.len() {
        *hash ^= bytes[i] as u64;
        *hash = hash.wrapping_mul(0x0000_0100_0000_01b3);
        i += 1;
    }
}

const FNV1A_OFFSET_BASIS: u64 = 0xcbf2_9ce4_8422_2325;

fn foreign_error_tag(error: ForeignError) -> u8 {
    match error {
        ForeignError::BadMagic => 1,
        ForeignError::UnsupportedVersion => 2,
        ForeignError::WrongArchitecture => 3,
        ForeignError::WrongSize => 4,
        ForeignError::UnknownCode => 5,
        ForeignError::NonzeroFlags => 6,
        ForeignError::NonzeroReserved => 7,
        ForeignError::WrongDomain => 8,
        ForeignError::WrongWireSize => 9,
        ForeignError::WrongProtocolVersion => 10,
        ForeignError::InvalidKickOrigin => 11,
        ForeignError::InvalidWaitOutcome => 12,
        ForeignError::WrongWaitRequestMagic => 13,
        ForeignError::WrongWaitRequestSize => 14,
        ForeignError::InvalidWaitRequest => 15,
    }
}

fn exit_reason_tag(reason: ExitReason) -> u8 {
    match reason {
        ExitReason::SupervisorCall => 1,
        ExitReason::Exception => 2,
        ExitReason::TaskDeath => 3,
        ExitReason::Kick => 4,
        ExitReason::WaitComplete => 5,
    }
}

fn reply_kind_tag(kind: ReplyKind) -> u8 {
    match kind {
        ReplyKind::Resume => 1,
        ReplyKind::Terminate => 2,
    }
}

fn wait_operation_tag(operation: WaitOperation) -> u8 {
    match operation {
        WaitOperation::Park => 1,
        WaitOperation::Wake => 2,
        WaitOperation::Requeue => 3,
        WaitOperation::Interrupt => 4,
    }
}

/// Replay the exact frozen fuzz corpus (two loops of 16384 cases, one shared
/// SplitMix64 stream seeded with `0x4c4f_4c4f_4d38_4655`) and fold an FNV-1a
/// digest over each input buffer, its decode/classify outcome tags, and the
/// re-encoded bytes. Adding the hashing consumes no RNG words, so the corpus is
/// byte-identical to the original test.
fn compute_fuzz_corpus_digest() -> u64 {
    const CASES: usize = 16_384;
    let mut hash: u64 = FNV1A_OFFSET_BASIS;
    let mut seed = 0x4c4f_4c4f_4d38_4655_u64;
    let stopped = Aarch64StateV1::default();

    for _ in 0..CASES {
        let mut bytes = ForeignMessageV1::new_exit_for_version(
            FOREIGN_VERSION_V4,
            ExitReason::SupervisorCall,
            7,
            11,
            13,
            stopped,
        )
        .expect("V4 supervisor-call frame is valid")
        .to_wire_bytes();
        let mutations = usize::try_from(next_fuzz_word(&mut seed) % 8 + 1)
            .expect("small mutation count fits usize");
        for _ in 0..mutations {
            let index = usize::try_from(
                next_fuzz_word(&mut seed) % FOREIGN_MESSAGE_V1_WIRE_SIZE as u64,
            )
            .expect("wire index fits usize");
            bytes[index] ^= next_fuzz_word(&mut seed) as u8;
        }

        fnv1a_update(&mut hash, &bytes);
        let decoded = ForeignMessageV1::from_wire_bytes(&bytes)
            .expect("an exact-width record must always decode losslessly");
        fnv1a_update(&mut hash, &decoded.to_wire_bytes());
        let exit_tag = match decoded.exit_reason() {
            Ok(reason) => exit_reason_tag(reason),
            Err(error) => 0x80 | foreign_error_tag(error),
        };
        let reply_tag = match decoded
            .validate_reply_for_version(decoded.domain_id, FOREIGN_VERSION_V4)
        {
            Ok(kind) => reply_kind_tag(kind),
            Err(error) => 0x80 | foreign_error_tag(error),
        };
        fnv1a_update(&mut hash, &[0xd1, exit_tag, reply_tag]);
    }

    for _ in 0..CASES {
        let mut bytes = [0_u8; FOREIGN_WAIT_U32_REQUEST_V1_WIRE_SIZE];
        for byte in &mut bytes {
            *byte = next_fuzz_word(&mut seed) as u8;
        }
        let length = usize::try_from(
            next_fuzz_word(&mut seed) % (FOREIGN_WAIT_U32_REQUEST_V1_WIRE_SIZE as u64 + 2),
        )
        .expect("fuzz length fits usize");
        let input = if length <= bytes.len() {
            &bytes[..length]
        } else {
            &bytes[..]
        };

        fnv1a_update(&mut hash, input);
        let outcome_tag = match ForeignWaitU32RequestV1::from_wire_bytes(input) {
            Ok(request) => {
                fnv1a_update(&mut hash, &request.to_wire_bytes());
                wait_operation_tag(request.operation)
            }
            Err(error) => 0x80 | foreign_error_tag(error),
        };
        fnv1a_update(&mut hash, &[0xd2, length as u8, outcome_tag]);
    }

    hash
}

