    assert_eq!(v2_kick_exit(KickOrigin::Asynchronous).to_wire_bytes(), GOLDEN_V2_KICK_ASYNCHRONOUS);
    assert_eq!(v2_kick_exit(KickOrigin::SupervisorCall).to_wire_bytes(), GOLDEN_V2_KICK_SUPERVISOR_CALL);
