#[test]
fn wire_field_offsets_carry_expected_le_values() {
    let bytes = v1_supervisor_exit().to_wire_bytes();
    assert_eq!(&bytes[0..4], b"LFOR");
    assert_eq!(&bytes[0..4], &FOREIGN_MAGIC.to_le_bytes());
    assert_eq!(&bytes[4..6], &FOREIGN_VERSION_V1.to_le_bytes());
    assert_eq!(&bytes[6..8], &FOREIGN_ARCH_AARCH64.to_le_bytes());
    assert_eq!(&bytes[8..12], &FOREIGN_MESSAGE_V1_SIZE.to_le_bytes());
    assert_eq!(&bytes[12..16], &EXIT_SUPERVISOR_CALL.to_le_bytes());
    assert_eq!(&bytes[16..24], &0x1122_3344_5566_7788_u64.to_le_bytes());
    assert_eq!(&bytes[24..32], &0x99aa_bbcc_ddee_ff00_u64.to_le_bytes());
    assert_eq!(&bytes[32..40], &0x0102_0304_0506_0708_u64.to_le_bytes());
    assert_eq!(&bytes[40..48], &[0_u8; 8]);
    // Embedded state header starts at offset 48.
    assert_eq!(&bytes[48..52], b"LOLO");
    assert_eq!(&bytes[48..52], &STATE_MAGIC.to_le_bytes());
    // V1 exit tail is all zero.
    assert_eq!(&bytes[944..976], &[0_u8; 32]);
}

#[test]
fn sequence_token_survives_wire_at_fixed_offset() {
    let message = v1_supervisor_exit();
    let bytes = message.to_wire_bytes();
    assert_eq!(&bytes[32..40], &message.sequence.to_le_bytes());
    let decoded = ForeignMessageV1::from_wire_bytes(&bytes).expect("decodes");
    assert_eq!(decoded.sequence, message.sequence);
}

// ======================================================================
// Decode golden vectors: decoding the frozen bytes must reproduce the exact
// value and every semantic accessor. These bytes are frozen, so the decode is
// independent of this crate's own to_wire_bytes.
// ======================================================================

#[test]
fn golden_v1_exits_decode_exactly() {
    let sup = ForeignMessageV1::from_wire_bytes(&GOLDEN_V1_SUPERVISOR_EXIT).expect("decodes");
    assert_eq!(sup, v1_supervisor_exit());
    assert_eq!(sup.exit_reason(), Ok(ExitReason::SupervisorCall));
    assert_eq!(sup.header.code, EXIT_SUPERVISOR_CALL);
    assert_eq!(sup.domain_id, 0x1122_3344_5566_7788);
    assert_eq!(sup.task_id, 0x99aa_bbcc_ddee_ff00);
    assert_eq!(sup.sequence, 0x0102_0304_0506_0708);

    let exc = ForeignMessageV1::from_wire_bytes(&GOLDEN_V1_EXCEPTION_EXIT).expect("decodes");
    assert_eq!(exc, v1_exception_exit());
    assert_eq!(exc.exit_reason(), Ok(ExitReason::Exception));

    let death = ForeignMessageV1::from_wire_bytes(&GOLDEN_V1_TASK_DEATH_EXIT).expect("decodes");
    assert_eq!(death, v1_task_death_exit());
    assert_eq!(death.exit_reason(), Ok(ExitReason::TaskDeath));
}

#[test]
fn golden_v2_kick_decodes_with_origins() {
    for (fixture, origin) in [
        (&GOLDEN_V2_KICK_ASYNCHRONOUS, KickOrigin::Asynchronous),
        (&GOLDEN_V2_KICK_SUPERVISOR_CALL, KickOrigin::SupervisorCall),
        (&GOLDEN_V2_KICK_EXCEPTION, KickOrigin::Exception),
    ] {
        let decoded = ForeignMessageV1::from_wire_bytes(fixture).expect("decodes");
        assert_eq!(decoded, v2_kick_exit(origin));
        assert_eq!(decoded.header.version, FOREIGN_VERSION_V2);
        assert_eq!(decoded.exit_reason(), Ok(ExitReason::Kick));
        assert_eq!(decoded.kick_origin(), Ok(origin));
    }
}

#[test]
fn golden_v3_wait_decodes_with_outcomes() {
    for (fixture, outcome) in [
        (&GOLDEN_V3_WAIT_WOKEN, WaitOutcome::Woken),
        (&GOLDEN_V3_WAIT_TIMED_OUT, WaitOutcome::TimedOut),
        (&GOLDEN_V3_WAIT_INTERRUPTED, WaitOutcome::Interrupted),
        (&GOLDEN_V3_WAIT_MAPPING_INVALIDATED, WaitOutcome::MappingInvalidated),
    ] {
        let decoded = ForeignMessageV1::from_wire_bytes(fixture).expect("decodes");
        assert_eq!(decoded, v3_wait_complete_exit(outcome));
        assert_eq!(decoded.header.version, FOREIGN_VERSION_V3);
        assert_eq!(decoded.exit_reason(), Ok(ExitReason::WaitComplete));
        assert_eq!(decoded.wait_outcome(), Ok(outcome));
    }
}

#[test]
fn golden_v4_frames_decode_exactly() {
    let wait = ForeignMessageV1::from_wire_bytes(&GOLDEN_V4_WAIT_COMPLETE).expect("decodes");
    assert_eq!(wait, v4_wait_complete_exit());
    assert_eq!(wait.header.version, FOREIGN_VERSION_V4);
    assert_eq!(wait.exit_reason(), Ok(ExitReason::WaitComplete));
    assert_eq!(wait.wait_outcome(), Ok(WaitOutcome::Woken));

    let kick = ForeignMessageV1::from_wire_bytes(&GOLDEN_V4_KICK).expect("decodes");
    assert_eq!(kick, v4_kick_exit());
    assert_eq!(kick.header.version, FOREIGN_VERSION_V4);
    assert_eq!(kick.exit_reason(), Ok(ExitReason::Kick));
    assert_eq!(kick.kick_origin(), Ok(KickOrigin::Exception));
}

#[test]
fn golden_replies_decode_and_validate() {
    let resume = ForeignMessageV1::from_wire_bytes(&GOLDEN_RESUME_REPLY).expect("decodes");
    assert_eq!(resume, resume_reply());
    assert_eq!(resume.validate_reply(0x1122_3344_5566_7788), Ok(ReplyKind::Resume));
    assert_eq!(resume.validate_reply(0), Err(ForeignError::WrongDomain));

    let terminate = ForeignMessageV1::from_wire_bytes(&GOLDEN_TERMINATE_REPLY).expect("decodes");
    assert_eq!(terminate, terminate_reply());
    assert_eq!(terminate.validate_reply(0x1122_3344_5566_7788), Ok(ReplyKind::Terminate));
}

#[test]
fn golden_wait_requests_decode_all_fields() {
    let park_nt = ForeignWaitU32RequestV1::from_wire_bytes(&GOLDEN_WAIT_PARK_NO_TIMEOUT).expect("decodes");
    assert_eq!(park_nt, wait_park_no_timeout());
    assert_eq!(park_nt.operation, WaitOperation::Park);
    assert_eq!(park_nt.sequence, 0x1122_3344_5566_7788);
    assert_eq!(park_nt.address, 0x0000_0000_0000_4000);
    assert_eq!(park_nt.expected, 0xfeed_beef);
    assert_eq!(park_nt.count, 0);
    assert_eq!(park_nt.timeout_ns, FOREIGN_WAIT_U32_NO_TIMEOUT);
    assert_eq!(park_nt.address2, 0);
    assert_eq!(park_nt.requeue_count, 0);

    let park_t = ForeignWaitU32RequestV1::from_wire_bytes(&GOLDEN_WAIT_PARK_TIMEOUT).expect("decodes");
    assert_eq!(park_t, wait_park_timeout());
    assert_eq!(park_t.timeout_ns, 0x0102_0304_0506_0708);

    let wake = ForeignWaitU32RequestV1::from_wire_bytes(&GOLDEN_WAIT_WAKE).expect("decodes");
    assert_eq!(wake, wait_wake());
    assert_eq!(wake.operation, WaitOperation::Wake);
    assert_eq!(wake.address, 0x0000_0000_cafe_0000);
    assert_eq!(wake.count, 0x1234_5678);

    let requeue = ForeignWaitU32RequestV1::from_wire_bytes(&GOLDEN_WAIT_REQUEUE).expect("decodes");
    assert_eq!(requeue, wait_requeue());
    assert_eq!(requeue.operation, WaitOperation::Requeue);
    assert_eq!(requeue.address, 0x0000_0000_1111_0000);
    assert_eq!(requeue.count, 0x0000_0007);
    assert_eq!(requeue.address2, 0x0000_0000_2222_0000);
    assert_eq!(requeue.requeue_count, 0x0000_0009);

    let interrupt = ForeignWaitU32RequestV1::from_wire_bytes(&GOLDEN_WAIT_INTERRUPT).expect("decodes");
    assert_eq!(interrupt, wait_interrupt());
    assert_eq!(interrupt.operation, WaitOperation::Interrupt);
    assert_eq!(interrupt.sequence, 0xaabb_ccdd_eeff_0011);
}

#[test]
fn fixtures_decode_encode_is_identity() {
    for fixture in [
        &GOLDEN_V1_SUPERVISOR_EXIT,
        &GOLDEN_V1_EXCEPTION_EXIT,
        &GOLDEN_V1_TASK_DEATH_EXIT,
        &GOLDEN_V2_KICK_ASYNCHRONOUS,
        &GOLDEN_V2_KICK_SUPERVISOR_CALL,
        &GOLDEN_V2_KICK_EXCEPTION,
        &GOLDEN_V3_WAIT_WOKEN,
        &GOLDEN_V3_WAIT_TIMED_OUT,
        &GOLDEN_V3_WAIT_INTERRUPTED,
        &GOLDEN_V3_WAIT_MAPPING_INVALIDATED,
        &GOLDEN_V4_WAIT_COMPLETE,
        &GOLDEN_V4_KICK,
        &GOLDEN_RESUME_REPLY,
        &GOLDEN_TERMINATE_REPLY,
    ] {
        let decoded = ForeignMessageV1::from_wire_bytes(fixture).expect("decodes");
        assert_eq!(&decoded.to_wire_bytes(), fixture);
    }
    for fixture in [
        &GOLDEN_WAIT_PARK_NO_TIMEOUT,
        &GOLDEN_WAIT_PARK_TIMEOUT,
        &GOLDEN_WAIT_WAKE,
        &GOLDEN_WAIT_REQUEUE,
        &GOLDEN_WAIT_INTERRUPT,
    ] {
        let decoded = ForeignWaitU32RequestV1::from_wire_bytes(fixture).expect("decodes");
        assert_eq!(&decoded.to_wire_bytes(), fixture);
    }
}

