#[test]
fn hostile_truncated_and_oversized_messages_are_rejected() {
    assert_eq!(ForeignMessageV1::from_wire_bytes(&HOSTILE_MSG_TRUNCATED_975), Err(ForeignError::WrongWireSize));
    assert_eq!(ForeignMessageV1::from_wire_bytes(&HOSTILE_MSG_TRUNCATED_512), Err(ForeignError::WrongWireSize));
    assert_eq!(ForeignMessageV1::from_wire_bytes(&HOSTILE_MSG_TRUNCATED_0), Err(ForeignError::WrongWireSize));
    assert_eq!(ForeignMessageV1::from_wire_bytes(&HOSTILE_MSG_OVERSIZED_977), Err(ForeignError::WrongWireSize));
}

#[test]
fn hostile_semantic_frames_are_rejected_by_exit_reason() {
    // from_wire_bytes is lossless; the rejection is at exit_reason().
    assert_eq!(ForeignMessageV1::from_wire_bytes(&HOSTILE_MSG_BAD_MAGIC).unwrap().exit_reason(), Err(ForeignError::BadMagic));
    assert_eq!(ForeignMessageV1::from_wire_bytes(&HOSTILE_MSG_VERSION_0).unwrap().exit_reason(), Err(ForeignError::UnsupportedVersion));
    assert_eq!(ForeignMessageV1::from_wire_bytes(&HOSTILE_MSG_VERSION_5).unwrap().exit_reason(), Err(ForeignError::UnsupportedVersion));
    assert_eq!(ForeignMessageV1::from_wire_bytes(&HOSTILE_MSG_WRONG_ARCH).unwrap().exit_reason(), Err(ForeignError::WrongArchitecture));
    assert_eq!(ForeignMessageV1::from_wire_bytes(&HOSTILE_MSG_WRONG_SIZE).unwrap().exit_reason(), Err(ForeignError::WrongSize));
    assert_eq!(ForeignMessageV1::from_wire_bytes(&HOSTILE_MSG_NONZERO_RESERVED).unwrap().exit_reason(), Err(ForeignError::NonzeroReserved));
}

#[test]
fn hostile_invalid_kick_origin_is_rejected() {
    let decoded = ForeignMessageV1::from_wire_bytes(&HOSTILE_MSG_INVALID_KICK_ORIGIN).unwrap();
    assert_eq!(decoded.exit_reason(), Err(ForeignError::InvalidKickOrigin));
    assert_eq!(decoded.kick_origin(), Err(ForeignError::InvalidKickOrigin));
}

#[test]
fn hostile_invalid_wait_outcome_is_rejected() {
    let decoded = ForeignMessageV1::from_wire_bytes(&HOSTILE_MSG_INVALID_WAIT_OUTCOME).unwrap();
    assert_eq!(decoded.exit_reason(), Err(ForeignError::InvalidWaitOutcome));
    assert_eq!(decoded.wait_outcome(), Err(ForeignError::InvalidWaitOutcome));
}

#[test]
fn hostile_wait_requests_are_rejected() {
    assert_eq!(ForeignWaitU32RequestV1::from_wire_bytes(&HOSTILE_WAIT_BAD_MAGIC), Err(ForeignError::WrongWaitRequestMagic));
    assert_eq!(ForeignWaitU32RequestV1::from_wire_bytes(&HOSTILE_WAIT_WRONG_VERSION), Err(ForeignError::WrongWaitRequestSize));
    assert_eq!(ForeignWaitU32RequestV1::from_wire_bytes(&HOSTILE_WAIT_WRONG_SIZE_FIELD), Err(ForeignError::WrongWaitRequestSize));
    assert_eq!(ForeignWaitU32RequestV1::from_wire_bytes(&HOSTILE_WAIT_NONZERO_RESERVED_TAIL), Err(ForeignError::WrongWaitRequestSize));
    assert_eq!(ForeignWaitU32RequestV1::from_wire_bytes(&HOSTILE_WAIT_UNKNOWN_OP_0), Err(ForeignError::InvalidWaitRequest));
    assert_eq!(ForeignWaitU32RequestV1::from_wire_bytes(&HOSTILE_WAIT_UNKNOWN_OP_5), Err(ForeignError::InvalidWaitRequest));
    assert_eq!(ForeignWaitU32RequestV1::from_wire_bytes(&HOSTILE_WAIT_TRUNCATED_63), Err(ForeignError::WrongWaitRequestSize));
    assert_eq!(ForeignWaitU32RequestV1::from_wire_bytes(&HOSTILE_WAIT_OVERSIZED_65), Err(ForeignError::WrongWaitRequestSize));
}

#[test]
fn interrupt_requires_nonzero_sequence() {
    assert_eq!(ForeignWaitU32RequestV1::interrupt(0).validate(), Err(ForeignError::InvalidWaitRequest));
}

// ======================================================================
// Numeric pinning: every public constant, every repr(C) layout (including the
// sub-record alignments the existing tests miss), and every private wire
// discriminant probed through the public encode API.
// ======================================================================

#[test]
fn magic_constants_are_frozen() {
    assert_eq!(FOREIGN_MAGIC, u32::from_le_bytes(*b"LFOR"));
    assert_eq!(FOREIGN_WAIT_U32_MAGIC, u32::from_le_bytes(*b"LWAT"));
    assert_eq!(STATE_MAGIC, u32::from_le_bytes(*b"LOLO"));
    assert_ne!(FOREIGN_MAGIC, STATE_MAGIC);
}

#[test]
fn magics_appear_as_le_prefixes_on_wire() {
    assert_eq!(&v1_supervisor_exit().to_wire_bytes()[0..4], b"LFOR");
    assert_eq!(&v1_supervisor_exit().to_wire_bytes()[0..4], &FOREIGN_MAGIC.to_le_bytes());
    assert_eq!(&v1_supervisor_exit().to_wire_bytes()[48..52], b"LOLO");
    assert_eq!(&wait_park_no_timeout().to_wire_bytes()[0..4], b"LWAT");
    assert_eq!(&wait_park_no_timeout().to_wire_bytes()[0..4], &FOREIGN_WAIT_U32_MAGIC.to_le_bytes());
    assert_eq!(&wait_park_no_timeout().to_wire_bytes()[4..6], &FOREIGN_WAIT_U32_VERSION_V1.to_le_bytes());
    assert_eq!(&wait_park_no_timeout().to_wire_bytes()[8..12], &(FOREIGN_WAIT_U32_REQUEST_V1_WIRE_SIZE as u32).to_le_bytes());
}

#[test]
fn protocol_and_arch_versions_are_frozen() {
    assert_eq!(FOREIGN_VERSION_V1, 1);
    assert_eq!(FOREIGN_VERSION_V2, 2);
    assert_eq!(FOREIGN_VERSION_V3, 3);
    assert_eq!(FOREIGN_VERSION_V4, 4);
    assert_eq!(FOREIGN_WAIT_U32_VERSION_V1, 1);
    assert_eq!(STATE_VERSION_V1, 1);
    assert_eq!(FOREIGN_ARCH_AARCH64, 1);
    assert_eq!(ARCHITECTURE_AARCH64, 1);
    assert_eq!(FOREIGN_ARCH_AARCH64, ARCHITECTURE_AARCH64);
    assert_eq!(FOREIGN_WAIT_U32_NO_TIMEOUT, u64::MAX);
    assert!(protocol_version_is_supported(FOREIGN_VERSION_V1));
    assert!(protocol_version_is_supported(FOREIGN_VERSION_V4));
    assert!(!protocol_version_is_supported(0));
    assert!(!protocol_version_is_supported(5));
}

#[test]
fn exit_reason_codes_are_frozen() {
    assert_eq!(EXIT_SUPERVISOR_CALL, 1);
    assert_eq!(EXIT_EXCEPTION, 2);
    assert_eq!(EXIT_TASK_DEATH, 3);
    assert_eq!(EXIT_KICK, 4);
    assert_eq!(EXIT_WAIT_COMPLETE, 5);
}

#[test]
fn reply_kind_codes_are_frozen() {
    assert_eq!(REPLY_RESUME, 0x101);
    assert_eq!(REPLY_TERMINATE, 0x102);
}

#[test]
fn exception_kind_values_are_frozen() {
    assert_eq!(EXCEPTION_NONE, 0);
    assert_eq!(EXCEPTION_SUPERVISOR_CALL, 1);
    assert_eq!(EXCEPTION_DATA_ABORT, 2);
    assert_eq!(EXCEPTION_INSTRUCTION_ABORT, 3);
    assert_eq!(EXCEPTION_ILLEGAL_INSTRUCTION, 4);
    assert_eq!(EXCEPTION_BREAKPOINT, 5);
    assert_eq!(EXCEPTION_OTHER, u32::MAX);
}

#[test]
fn domain_op_opcodes_are_frozen() {
    assert_eq!(domain_op::SET_CAPACITY, 0);
    assert_eq!(domain_op::ATTACH, 1);
    assert_eq!(domain_op::START, 2);
    assert_eq!(domain_op::DESTROY, 3);
    assert_eq!(domain_op::SET_PROTOCOL_VERSION, 4);
    assert_eq!(domain_op::KICK, 5);
    assert_eq!(domain_op::CANCEL, 6);
    assert_eq!(domain_op::SET_LIMITS_V1, 7);
    assert_eq!(FOREIGN_DOMAIN_LIMITS_V1_VALUE_COUNT, 6);
    assert_eq!(FOREIGN_DOMAIN_LIMITS_V1_CONTROL_WORD_COUNT, 7);
}

#[test]
fn wait_and_memory_constants_are_frozen() {
    assert_eq!(FOREIGN_WAIT_U32_REQUEST_V1_WIRE_SIZE, 64);
    assert_eq!(FOREIGN_WAIT_U32_NO_TIMEOUT, u64::MAX);
    assert_eq!(FOREIGN_MEMORY_VERSION_V1, 1);
    assert_eq!(FOREIGN_MEMORY_MAX_TRANSFER_V1, 64 * 1024);
    assert_eq!(FOREIGN_MEMORY_HANDLE_PREFIX, "memory/");
    assert_eq!(FOREIGN_ATOMIC_U32_HANDLE_PREFIX, "atomic-u32/");
    assert_eq!(FOREIGN_WAIT_U32_HANDLE_PREFIX, "wait-u32/");
}

#[test]
fn wire_sizes_are_frozen() {
    assert_eq!(STATE_V1_SIZE, 896);
    assert_eq!(FOREIGN_MESSAGE_V1_SIZE, 976);
    assert_eq!(FOREIGN_MESSAGE_V1_WIRE_SIZE, 976);
    assert_eq!(FOREIGN_WAIT_U32_REQUEST_V1_WIRE_SIZE, 64);
}

#[test]
fn foreign_message_layout_is_frozen() {
    assert_eq!(size_of::<ForeignMessageV1>(), 976);
    assert_eq!(align_of::<ForeignMessageV1>(), 16);
    assert_eq!(offset_of!(ForeignMessageV1, header), 0);
    assert_eq!(offset_of!(ForeignMessageV1, domain_id), 16);
    assert_eq!(offset_of!(ForeignMessageV1, task_id), 24);
    assert_eq!(offset_of!(ForeignMessageV1, sequence), 32);
    assert_eq!(offset_of!(ForeignMessageV1, flags), 40);
    assert_eq!(offset_of!(ForeignMessageV1, state), 48);
    assert_eq!(offset_of!(ForeignMessageV1, reserved), 944);
    assert_eq!(offset_of!(ForeignMessageV1, reserved) + size_of::<[u64; 4]>(), 976);
}

#[test]
fn foreign_header_layout_is_frozen() {
    // The existing suite pins size but never the alignment.
    assert_eq!(size_of::<ForeignHeader>(), 16);
    assert_eq!(align_of::<ForeignHeader>(), 4);
    assert_eq!(offset_of!(ForeignHeader, magic), 0);
    assert_eq!(offset_of!(ForeignHeader, version), 4);
    assert_eq!(offset_of!(ForeignHeader, architecture), 6);
    assert_eq!(offset_of!(ForeignHeader, size), 8);
    assert_eq!(offset_of!(ForeignHeader, code), 12);
}

#[test]
fn state_layout_is_frozen() {
    assert_eq!(size_of::<Aarch64StateV1>(), 896);
    assert_eq!(align_of::<Aarch64StateV1>(), 16);
    assert_eq!(offset_of!(Aarch64StateV1, header), 0);
    assert_eq!(offset_of!(Aarch64StateV1, x), 16);
    assert_eq!(offset_of!(Aarch64StateV1, sp), 264);
    assert_eq!(offset_of!(Aarch64StateV1, pc), 272);
    assert_eq!(offset_of!(Aarch64StateV1, pstate), 280);
    assert_eq!(offset_of!(Aarch64StateV1, tpidr_el0), 288);
    assert_eq!(offset_of!(Aarch64StateV1, tpidrro_el0), 296);
    assert_eq!(offset_of!(Aarch64StateV1, vectors), 304);
    assert_eq!(offset_of!(Aarch64StateV1, fpcr), 816);
    assert_eq!(offset_of!(Aarch64StateV1, fpsr), 820);
    assert_eq!(offset_of!(Aarch64StateV1, exception), 824);
    assert_eq!(offset_of!(Aarch64StateV1, reserved), 856);
    assert_eq!(offset_of!(Aarch64StateV1, reserved) + size_of::<[u64; 5]>(), 896);
}

#[test]
fn state_subrecord_layouts_are_frozen() {
    // Sub-record alignments the existing suite never pins.
    assert_eq!(size_of::<StateHeader>(), 16);
    assert_eq!(align_of::<StateHeader>(), 4);
    assert_eq!(size_of::<Aarch64ExceptionState>(), 32);
    assert_eq!(align_of::<Aarch64ExceptionState>(), 8);
    assert_eq!(size_of::<Aarch64Vector>(), 16);
    assert_eq!(align_of::<Aarch64Vector>(), 16);
    assert_eq!(offset_of!(Aarch64ExceptionState, kind), 0);
    assert_eq!(offset_of!(Aarch64ExceptionState, flags), 4);
    assert_eq!(offset_of!(Aarch64ExceptionState, esr), 8);
    assert_eq!(offset_of!(Aarch64ExceptionState, far), 16);
    assert_eq!(offset_of!(Aarch64ExceptionState, pc), 24);
}

#[test]
fn wait_request_wire_size_is_frozen_64() {
    assert_eq!(FOREIGN_WAIT_U32_REQUEST_V1_WIRE_SIZE, 64);
    assert_eq!(wait_park_no_timeout().to_wire_bytes().len(), 64);
}

#[test]
fn kick_origin_wire_encoding_is_frozen() {
    // KICK_ORIGIN_* are private; probe them through the encode path.
    assert_eq!(reserved0_on_wire(&v2_kick_exit(KickOrigin::Asynchronous)), 0);
    assert_eq!(reserved0_on_wire(&v2_kick_exit(KickOrigin::SupervisorCall)), 1);
    assert_eq!(reserved0_on_wire(&v2_kick_exit(KickOrigin::Exception)), 2);
}

#[test]
fn wait_outcome_wire_encoding_is_frozen() {
    // WAIT_OUTCOME_* are private; probe them through the encode path.
    assert_eq!(reserved0_on_wire(&v3_wait_complete_exit(WaitOutcome::Woken)), 0);
    assert_eq!(reserved0_on_wire(&v3_wait_complete_exit(WaitOutcome::TimedOut)), 1);
    assert_eq!(reserved0_on_wire(&v3_wait_complete_exit(WaitOutcome::Interrupted)), 2);
    assert_eq!(reserved0_on_wire(&v3_wait_complete_exit(WaitOutcome::MappingInvalidated)), 3);
}

#[test]
fn wait_operation_wire_encoding_is_frozen() {
    // WAIT_OPERATION_* are private; probe them through the encode path.
    assert_eq!(operation_on_wire(&wait_park_no_timeout()), 1);
    assert_eq!(operation_on_wire(&wait_wake()), 2);
    assert_eq!(operation_on_wire(&wait_requeue()), 3);
    assert_eq!(operation_on_wire(&wait_interrupt()), 4);
}

// ======================================================================
// Fuzz-corpus digest (32,768 frozen cases). Recomputed by this crate and
// asserted equal, so any seed / constant / decode-behavior drift fails.
// ======================================================================

const GOLDEN_FUZZ_CORPUS_DIGEST: u64 = 0x9ad231ae3840a039;

#[test]
fn fuzz_corpus_digest_is_reproducible() {
    // Re-runs the exact 16384x2 frozen corpus through this crate's API and
    // asserts the FNV-1a digest matches the value captured from the old crate.
    assert_eq!(compute_fuzz_corpus_digest(), GOLDEN_FUZZ_CORPUS_DIGEST);
}
